from PIL import Image
import numpy as np, colorsys
im=np.array(Image.open('first_frame.png').convert('RGB'))
def ch(p):
 r,g,b=p/255.; mx=max(r,g,b); mn=min(r,g,b); c=mx-mn
 if mx<.12:return '@'
 if c<.07:return ' ' if mx>.82 else ('.' if mx>.66 else (':' if mx>.50 else ('+' if mx>.34 else ('*' if mx>.20 else '%'))))
 h,s,v=colorsys.rgb_to_hsv(r,g,b)
 if h<.07 or h>.96:return 'R' if v>.55 else ('r' if v>.35 else '1')
 if h<.13:return 'O' if v>.55 else ('o' if v>.35 else '2')
 if h<.22:return 'Y' if v>.55 else ('y' if v>.35 else '3')
 if h<.45:return 'G' if v>.50 else ('g' if v>.30 else '4')
 if h<.58:return 'C' if v>.50 else ('c' if v>.30 else '5')
 if h<.75:return 'B' if v>.50 else ('b' if v>.30 else '6')
 return 'P' if v>.50 else ('p' if v>.30 else '7')
print('crop x52:120 y98:176 every 1 px, lines every 2 rows')
for y in range(98,176,2):
 row=''
 for x in range(52,120):
  p=im[y:y+2,x].mean(0)
  row+=ch(p)
 print(f'{y:3d} '+row)
PY"

